BEGIN
IF OBJECT_ID('dbo.db_SP_ActualizarDEFAULTS_SINCROVIEJA','P') IS NOT NULL	DROP PROCEDURE db_SP_ActualizarDEFAULTS
end
GO
CREATE PROCEDURE [dbo].[db_SP_ActualizarDEFAULTS_SINCROVIEJA]
 AS
	SET NOCOUNT ON;
	DECLARE @tabla		VARCHAR(100)
	DECLARE @campo		VARCHAR(100)
	DECLARE @tipo		VARCHAR(100)
	DECLARE @sql		NVARCHAR(MAX)
	DECLARE curTablas CURSOR
		FOR select col.TABLE_NAME,col.COLUMN_NAME,col.DATA_TYPE from INFORMATION_SCHEMA.COLUMNS col inner join INFORMATION_SCHEMA.TABLES tbl on tbl.TABLE_NAME=col.TABLE_NAME where tbl.TABLE_TYPE='BASE TABLE' and col.COLUMN_DEFAULT  is null and tbl.TABLE_NAME='GLB_terceros'
	OPEN curTablas 
	FETCH NEXT FROM curTablas InTO @tabla, @campo,@tipo
	WHILE @@FETCH_STATUS=0
	BEGIN
		IF(@tipo='decimal' or @tipo='numeric' or @tipo='int' or @tipo='bit')
		BEGIN
			set @sql='ALTER TABLE dbo.'+@tabla+' ADD CONSTRAINT DF_'+@tabla+'_'+@campo+' DEFAULT (0) FOR '+@campo+' WITH VALUES ;'
		END
		ELSE IF(@tipo='datetime' or @tipo='date')
		BEGIN
		set @sql='ALTER TABLE dbo.'+@tabla+' ADD  CONSTRAINT DF_'+@tabla+'_'+@campo+' DEFAULT (getdate()) FOR '+@campo+' WITH VALUES ;'
		END 
		ELSE
		BEGIN
		set @sql='ALTER TABLE dbo.'+@tabla+' ADD  CONSTRAINT DF_'+@tabla+'_'+@campo+' DEFAULT ('''') FOR '+@campo+' WITH VALUES ;'
		END
		BEGIN TRY
		EXEC (@sql)
		print @sql
		END TRY
		BEGIN CATCH
		print @sql + ' ERROR : '+ ERROR_MESSAGE();
		END CATCH
		FETCH NEXT FROM curTablas INTO  @tabla, @campo,@tipo
	END
	CLOSE curTablas
	DEALLOCATE curTablas
GO
BEGIN
IF NOT EXISTS(Select * From dbo.sysobjects Where name='esq_tablasprd')
begin 
CREATE TABLE [dbo].[esq_tablasprd](
	[NOMTABLA] [nvarchar](100) NOT NULL,
	[NOMCAMPO] [nvarchar](200) NOT NULL,
	[POSICION] [int] NOT NULL,
	[TIPODATO] [nvarchar](50) NOT NULL,
	[LONGITUD] [numeric](10, 0) NOT NULL,
	[POSDECIMAL] [numeric](10, 0) NOT NULL,
	[VLRDEFAULT] [nvarchar](50) NULL,
	[IDENTIDAD] [bit] NOT NULL DEFAULT ((0)),
	[NULLVALUES] [bit] NOT NULL DEFAULT ((0)),
	[PRIMARYKEY] [bit] NOT NULL DEFAULT ((0)),
	[CHECK_CONSTRAINT] [varchar](512) NOT NULL DEFAULT (''),
	[USUARIO] [nvarchar](100) NULL,
	[FECHACREACION] [datetime] NULL,
	[FECHAMODIFIC] [datetime] NULL,
	[ESTADO] [int] NOT NULL,
 CONSTRAINT [PK_ESQ_TABLASPRD] PRIMARY KEY CLUSTERED 
(
	[NOMTABLA] ASC,
	[NOMCAMPO] ASC
)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
) ON [PRIMARY]
end 
END
