BEGIN
declare @name nvarchar(max)
declare @sql2 nvarchar(max)
declare curdefaults cursor
	for select name from sys.objects where type ='D' and OBJECT_NAME(parent_object_id)='glb_terceros' 
	open curdefaults
	fetch next from curdefaults into @name
	while @@FETCH_STATUS=0
	begin
	set @sql2='alter table glb_terceros drop constraint '+@name
	begin try
	exec (@sql2)
	end try
	begin catch
	print 'ERROR: '+@sql2
	end catch
	FETCH NEXT FROM curdefaults InTO  @name
	END
	CLOSE curdefaults
	DEALLOCATE curdefaults
	End
GO
Begin
	declare @name nvarchar(max)
	declare @sql2 nvarchar(max)
	DECLARE @tabla		VARCHAR(100)
		DECLARE @campo		VARCHAR(100)
		DECLARE @sql		NVARCHAR(MAX)
		exec db_SP_Diagnostico_Estructuras_BD
		DECLARE curTablas CURSOR
			FOR SELECT	Temp.tabla,Temp.campo
			FROM	##tempDiagnostico Temp 
			WHERE Temp.estado='CNT' and temp.tabla='glb_terceros'
		OPEN curTablas 
		FETCH NEXT FROM curTablas InTO @tabla, @campo
		WHILE @@FETCH_STATUS=0
		BEGIN
			set @sql='ALTER TABLE '+@tabla+' Drop COLUMN '+ @campo
			begin try
			EXEC (@sql)
			end try
			begin catch
			print @sql + ' ERROR : '+ ERROR_MESSAGE();
			end catch
			FETCH NEXT FROM curTablas InTO  @tabla, @campo
		END
		CLOSE curTablas
		DEALLOCATE curTablas
END
GO
exec db_SP_ActualizarDEFAULTS_SINCROVIEJA
		